using GlowvaERP.Data;
using GlowvaERP.Helpers;

namespace GlowvaERP.Forms;

public sealed class ReportCenterForm : Form
{
    private readonly ComboBox _report=new();private readonly DateTimePicker _from=new();private readonly DateTimePicker _to=new();private readonly TextBox _search=new();private readonly DataGridView _grid=new();private readonly Label _total=new();
    public ReportCenterForm(string? initialReport=null){Text="مركز التقارير";Size=new Size(1250,720);StartPosition=FormStartPosition.CenterParent;RightToLeft=RightToLeft.Yes;BuildUi();if(!string.IsNullOrWhiteSpace(initialReport)){var i=_report.Items.IndexOf(initialReport);if(i>=0)_report.SelectedIndex=i;}Run();}
    private void BuildUi(){var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(10),RightToLeft=RightToLeft.Yes};root.RowStyles.Add(new RowStyle(SizeType.Absolute,85));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));var top=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=10,RightToLeft=RightToLeft.Yes};for(int i=0;i<10;i++)top.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,10));string[] reports={"تقرير المبيعات","تقرير المشتريات","مرتجعات المبيعات","مرتجعات المشتريات","تقرير المخزون","الأصناف الناقصة","حركة المخزون","كشف حساب العملاء","كشف حساب الموردين","تقرير الخزينة","تقرير المصروفات"};_report.Items.AddRange(reports);_report.DropDownStyle=ComboBoxStyle.DropDownList;_report.SelectedIndex=0;_report.Dock=DockStyle.Fill;_from.Value=DateTime.Today.AddMonths(-1);_from.Format=DateTimePickerFormat.Short;_from.Dock=DockStyle.Fill;_to.Value=DateTime.Today;_to.Format=DateTimePickerFormat.Short;_to.Dock=DockStyle.Fill;_search.Dock=DockStyle.Fill;_search.PlaceholderText="بحث اسم / كود / رقم";var run=new Button{Text="تشغيل",Dock=DockStyle.Fill,BackColor=Color.FromArgb(33,150,243),ForeColor=Color.White};run.Click+=(_,_)=>Run();var close=new Button{Text="إغلاق",Dock=DockStyle.Fill};close.Click+=(_,_)=>Close();top.Controls.Add(L("التقرير"),0,0);top.Controls.Add(_report,1,0);top.SetColumnSpan(_report,2);top.Controls.Add(L("من"),3,0);top.Controls.Add(_from,4,0);top.Controls.Add(L("إلى"),5,0);top.Controls.Add(_to,6,0);top.Controls.Add(_search,7,0);top.Controls.Add(run,8,0);top.Controls.Add(close,9,0);ScrollableLayout.ConfigureGrid(_grid,36);_grid.AutoGenerateColumns=true;var foot=new Panel{Dock=DockStyle.Fill};_total.Dock=DockStyle.Fill;_total.TextAlign=ContentAlignment.MiddleRight;_total.Font=new Font("Segoe UI",11,FontStyle.Bold);foot.Controls.Add(_total);root.Controls.Add(top,0,0);root.Controls.Add(_grid,0,1);root.Controls.Add(foot,0,2);Controls.Add(root);}
    private void Run(){try{using var c=Database.OpenConnection();using var cmd=c.CreateCommand();var r=_report.Text;var s=$"%{_search.Text.Trim()}%";cmd.Parameters.AddWithValue("$from",_from.Value.ToString("yyyy-MM-dd"));cmd.Parameters.AddWithValue("$to",_to.Value.ToString("yyyy-MM-dd"));cmd.Parameters.AddWithValue("$s",s);string sql;string totalSql;switch(r){case "تقرير المبيعات":sql="SELECT o.invoice_number AS رقم_الفاتورة,o.order_date AS التاريخ,COALESCE(c.name,'عميل نقدي') AS العميل,COALESCE(o.payment_status,'') AS الدفع,ROUND(COALESCE(SUM(oi.quantity*oi.unit_price),0)-o.discount,2) AS الإجمالي FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN order_items oi ON oi.order_id=o.id WHERE date(o.order_date) BETWEEN date($from) AND date($to) AND (COALESCE(c.name,'') LIKE $s OR CAST(o.invoice_number AS TEXT) LIKE $s) GROUP BY o.id ORDER BY o.id DESC;";totalSql="SELECT COALESCE(SUM(COALESCE((SELECT SUM(quantity*unit_price) FROM order_items WHERE order_id=o.id),0)-discount),0) FROM orders o WHERE date(order_date) BETWEEN date($from) AND date($to);";break;case "تقرير المشتريات":sql="SELECT p.invoice_number AS رقم_الفاتورة,p.purchase_date AS التاريخ,COALESCE(s.name,'') AS المورد,COALESCE(p.payment_status,'') AS الدفع,ROUND(COALESCE(SUM(pi.quantity*pi.unit_price),0)-p.discount,2) AS الإجمالي FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN purchase_items pi ON pi.purchase_id=p.id WHERE date(p.purchase_date) BETWEEN date($from) AND date($to) AND (COALESCE(s.name,'') LIKE $s OR CAST(p.invoice_number AS TEXT) LIKE $s) GROUP BY p.id ORDER BY p.id DESC;";totalSql="SELECT COALESCE(SUM(COALESCE((SELECT SUM(quantity*unit_price) FROM purchase_items WHERE purchase_id=p.id),0)-discount),0) FROM purchases p WHERE date(purchase_date) BETWEEN date($from) AND date($to);";break;case "مرتجعات المبيعات":sql="SELECT r.return_number AS رقم_المرتجع,r.return_date AS التاريخ,COALESCE(c.name,'') AS العميل,r.total AS الإجمالي,r.reason AS السبب FROM sales_returns r LEFT JOIN customers c ON c.id=r.customer_id WHERE date(r.return_date) BETWEEN date($from) AND date($to) ORDER BY r.id DESC;";totalSql="SELECT COALESCE(SUM(total),0) FROM sales_returns WHERE date(return_date) BETWEEN date($from) AND date($to);";break;case "مرتجعات المشتريات":sql="SELECT r.return_number AS رقم_المرتجع,r.return_date AS التاريخ,COALESCE(s.name,'') AS المورد,r.total AS الإجمالي,r.reason AS السبب FROM purchase_returns r LEFT JOIN suppliers s ON s.id=r.supplier_id WHERE date(r.return_date) BETWEEN date($from) AND date($to) ORDER BY r.id DESC;";totalSql="SELECT COALESCE(SUM(total),0) FROM purchase_returns WHERE date(return_date) BETWEEN date($from) AND date($to);";break;case "تقرير المخزون":sql="SELECT p.code AS الكود,p.name AS الصنف,p.category AS التصنيف,p.opening_stock+COALESCE((SELECT SUM(quantity_in-quantity_out) FROM inventory_ledger l WHERE l.product_id=p.id),0) AS الرصيد,p.sell_price AS سعر_البيع,p.buy_price AS سعر_الشراء,p.low_stock_threshold AS حد_الطلب FROM products p WHERE p.is_active=1 AND (p.name LIKE $s OR p.code LIKE $s) ORDER BY p.name;";totalSql="SELECT COALESCE(SUM(p.opening_stock+COALESCE((SELECT SUM(quantity_in-quantity_out) FROM inventory_ledger l WHERE l.product_id=p.id),0)),0) FROM products p WHERE p.is_active=1;";break;case "الأصناف الناقصة":sql="SELECT p.code AS الكود,p.name AS الصنف,p.low_stock_threshold AS حد_الطلب,p.opening_stock+COALESCE((SELECT SUM(quantity_in-quantity_out) FROM inventory_ledger l WHERE l.product_id=p.id),0) AS الرصيد FROM products p WHERE p.is_active=1 AND p.opening_stock+COALESCE((SELECT SUM(quantity_in-quantity_out) FROM inventory_ledger l WHERE l.product_id=p.id),0)<=p.low_stock_threshold ORDER BY الرصيد,p.name;";totalSql="SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND p.opening_stock+COALESCE((SELECT SUM(quantity_in-quantity_out) FROM inventory_ledger l WHERE l.product_id=p.id),0)<=p.low_stock_threshold;";break;case "حركة المخزون":sql="SELECT l.movement_date AS التاريخ,p.code AS الكود,p.name AS الصنف,l.movement_type AS الحركة,l.quantity_in AS وارد,l.quantity_out AS منصرف,l.unit_cost AS التكلفة,l.reference_type AS المرجع,l.reference_id AS رقم_المرجع,l.notes AS ملاحظات FROM inventory_ledger l JOIN products p ON p.id=l.product_id WHERE date(l.movement_date) BETWEEN date($from) AND date($to) AND (p.name LIKE $s OR p.code LIKE $s) ORDER BY l.movement_date DESC,l.id DESC;";totalSql="SELECT COALESCE(SUM(quantity_in-quantity_out),0) FROM inventory_ledger WHERE date(movement_date) BETWEEN date($from) AND date($to);";break;case "كشف حساب العملاء":sql="SELECT a.transaction_date AS التاريخ,COALESCE(c.name,'') AS العميل,a.reference_type AS المرجع,a.reference_id AS رقم_المرجع,a.debit AS مدين,a.credit AS دائن,a.debit-a.credit AS الحركة,a.notes AS ملاحظات FROM account_transactions a LEFT JOIN customers c ON c.id=a.party_id WHERE a.account_type='customer' AND date(a.transaction_date) BETWEEN date($from) AND date($to) AND c.name LIKE $s ORDER BY a.transaction_date DESC,a.id DESC;";totalSql="SELECT COALESCE(SUM(debit-credit),0) FROM account_transactions WHERE account_type='customer' AND date(transaction_date) BETWEEN date($from) AND date($to);";break;case "كشف حساب الموردين":sql="SELECT a.transaction_date AS التاريخ,COALESCE(s.name,'') AS المورد,a.reference_type AS المرجع,a.reference_id AS رقم_المرجع,a.debit AS مدين,a.credit AS دائن,a.credit-a.debit AS الحركة,a.notes AS ملاحظات FROM account_transactions a LEFT JOIN suppliers s ON s.id=a.party_id WHERE a.account_type='supplier' AND date(a.transaction_date) BETWEEN date($from) AND date($to) AND s.name LIKE $s ORDER BY a.transaction_date DESC,a.id DESC;";totalSql="SELECT COALESCE(SUM(credit-debit),0) FROM account_transactions WHERE account_type='supplier' AND date(transaction_date) BETWEEN date($from) AND date($to);";break;case "تقرير المصروفات":sql="SELECT expense_date AS التاريخ,category AS النوع,amount AS القيمة,notes AS ملاحظات FROM expenses WHERE date(expense_date) BETWEEN date($from) AND date($to) AND category LIKE $s ORDER BY expense_date DESC,id DESC;";totalSql="SELECT COALESCE(SUM(amount),0) FROM expenses WHERE date(expense_date) BETWEEN date($from) AND date($to);";break;default:sql="SELECT transaction_date AS التاريخ,transaction_type AS النوع,amount_in AS وارد,amount_out AS منصرف,amount_in-amount_out AS صافي,notes AS ملاحظات FROM cash_transactions WHERE date(transaction_date) BETWEEN date($from) AND date($to) ORDER BY transaction_date DESC,id DESC;";totalSql="SELECT COALESCE(SUM(amount_in-amount_out),0) FROM cash_transactions WHERE date(transaction_date) BETWEEN date($from) AND date($to);";break;}cmd.CommandText=sql;using var reader=cmd.ExecuteReader();var dt=new System.Data.DataTable();dt.Load(reader);_grid.DataSource=dt;using var total= c.CreateCommand();total.CommandText=totalSql;total.Parameters.AddWithValue("$from",_from.Value.ToString("yyyy-MM-dd"));total.Parameters.AddWithValue("$to",_to.Value.ToString("yyyy-MM-dd"));_total.Text=$"الإجمالي / صافي الحركة: {Convert.ToDecimal(total.ExecuteScalar()??0m):N2}";}catch(Exception ex){MessageBox.Show(this,ex.Message,"التقرير",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    private static Label L(string t)=>new(){Text=t,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight,Font=new Font("Segoe UI",9,FontStyle.Bold)};
}
